<?php require __DIR__.'/includes/layout.php'; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['delete_id']??0);if($id){$q=db()->prepare('DELETE FROM csSoftGroups WHERE ID=?');$q->execute([$id]);}redirect('groups.php');}$rows=db()->query('SELECT g.*,COUNT(p.ID) ProductCount FROM csSoftGroups g LEFT JOIN csSoftProducts p ON p.SoftGroupID=g.ID GROUP BY g.ID ORDER BY g.Name')->fetchAll();admin_header('Группы');?><div class="card"><div class="toolbar"><div><b>Служебный справочник</b><div class="help">Группы используются только в админке.</div></div><a class="btn primary" href="group-edit.php">+ Добавить группу</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Группа</th><th>Описание</th><th>Продуктов</th><th>Статус</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?=aesc(a_legacy($r['Name']))?></b></td><td><?=aesc(a_legacy($r['Description']??''))?></td><td><?=$r['ProductCount']?></td><td><span class="badge <?=$r['IsActive']?'on':'off'?>"><?=$r['IsActive']?'Активна':'Скрыта'?></span></td><td><div class="actions"><a class="btn" href="group-edit.php?id=<?=(int)$r['ID']?>">Изменить</a><?php if((int)$r['ProductCount']===0): ?><form method="post" onsubmit="return confirm('Удалить группу?')"><input type="hidden" name="_csrf" value="<?=aesc(csrf_token())?>"><input type="hidden" name="delete_id" value="<?=$r['ID']?>"><button class="btn danger" type="submit">Удалить</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></div><?php admin_footer();
